(function(){'use strict';function attach(){const btn=document.getElementById('mobilityQuote');if(!btn||!window.VertexTaxi)return;btn.textContent=document.documentElement.lang==='en'?'Order Vertex Taxi':'Заказать Vertex Taxi';btn.onclick=()=>window.VertexTaxi.open()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',attach);else attach();new MutationObserver(attach).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});})();